const CACHE='registro-mob-v5';const SHELL=['./','./index.html','./style.css','./app.js','./lines.json','./schedules.json','./routes.json','./journeys.json','./stops.json','./validation.json','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png','./vendor/leaflet.js','./vendor/leaflet.css'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const k of await caches.keys())if(k!==CACHE)await caches.delete(k);await self.clients.claim()})()));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith((async()=>{const c=await caches.open(CACHE);try{const r=await fetch(e.request);if(r.ok)await c.put(e.request,r.clone());return r}catch(error){const cached=await c.match(e.request,{ignoreSearch:e.request.mode==='navigate'});if(cached)return cached;if(e.request.mode==='navigate')return c.match('./index.html');throw error}})())});
